/*
	Grid and camera code (Buffer A and Common tabs) is from Jan Mróz (jaszunio15)
    https://www.shadertoy.com/view/Wtt3zj

	How to use:
	W A S D Q E keys - Camera movement
	Shift key - Adds more speed to camera movement
	Mouse - Look around
	G - enable/disable grid view
*/

#define CAMERA_FOV 1.1

vec3 uvToCastPlane(vec2 uv)
{
 	return vec3(uv.x, uv.y, CAMERA_FOV);   
}

float min3(vec3 v)
{
    return min(v.x, min(v.y, v.z));
}

float min4(vec4 v)
{
    return min(min(v.x, v.y), min(v.z, v.w));
}

float max3(vec3 v)
{
    return max(v.x, max(v.y, v.z));
}

float max4(vec4 v)
{
    return max(max(v.x, v.y), max(v.z, v.w));
}

vec2 BboxIntersect(vec3 ray_origin, vec3 ray_inv_dir, vec3 box_min, vec3 box_max, float t_min, float t_max)
{
    vec3 f = (box_max - ray_origin) * ray_inv_dir;
    vec3 n = (box_min - ray_origin) * ray_inv_dir;
    vec3 tmax = max(f, n);
    vec3 tmin = min(f, n);
    float max_t = min(min3(tmax), t_max);
    float min_t = max(max3(tmin), t_min);

    return vec2(min_t, max_t);
}

#define C01 0
#define C11 1
#define C10 2
#define C00 3

float Displacement(ivec2 coord)
{
    //return 1.0f;
    return texture(iChannel2, vec2(coord)/128.0f+vec2(iTime, iTime)*0.01).r*0.5+0.5;
}

vec4 SampleHeightMap(ivec2 coord)
{

    float h00 = max3(texture(iChannel1, vec2(coord+ivec2(0,0))/64.0f).rgb)*Displacement(coord+ivec2(0,0));
    float h01 = max3(texture(iChannel1, vec2(coord+ivec2(0,1))/64.0f).rgb)*Displacement(coord+ivec2(0,1));;
    float h10 = max3(texture(iChannel1, vec2(coord+ivec2(1,0))/64.0f).rgb)*Displacement(coord+ivec2(1,0));;
    float h11 = max3(texture(iChannel1, vec2(coord+ivec2(1,1))/64.0f).rgb)*Displacement(coord+ivec2(1,1));;

    return vec4(h01, h11, h10, h00);

}

bool IntersectTriangle(
    vec3 v1, vec3 v2, vec3 v3,
    vec3 rayOrigin, vec3 rayDirection, float tmin, float tmax,
    out float hitT)
{
    // Determine edge vectors for clockwise triangle vertices
    vec3 e1 = v2 - v1;
    vec3 e2 = v3 - v1;

    vec3 s1 = cross(rayDirection, e2);
    float determinant = dot(s1, e1);
    float invd = 1.0/(determinant);

    vec3 d = rayOrigin - v1;
    float u = dot(d, s1) * invd;

    float thickness = 0.02;
    // Barycentric coordinate U is outside range or triangle front/backface culled
    if (u < thickness || u > 1.f-thickness || determinant == 0.0f)
        return false;

    vec3 s2 = cross(d, e1);
    float v = dot(rayDirection, s2) * invd;

    // Barycentric coordinate V is outside range
    if ((v < thickness) || (u + v > 1.f-thickness))
        return false;

    // Check parametric distance
    float t = dot(e2, s2) * invd;
    if (t < tmin || t > tmax)
        return false;

    hitT = t;

    return true;
}

float IntersectMapTriangle(float C, float A, float B, vec3 rayOrigin, vec3 rayDirection, float X, float Z)
{
    return (-rayOrigin.y + A*(rayOrigin.x-X) + B*(rayOrigin.z-Z) + C) / (rayDirection.y -A*rayDirection.x - B*rayDirection.z);
}

void Swap(inout float a, inout float b)
{
    float temp = a;
    a = b;
    b = temp;
}

bool TraceRay(vec3 rayOrigin, vec3 rayDirection, out ivec2 hitTexel, out int hitTriangle)
{
   if (rayDirection.x == 0.0)
       rayDirection.x = 1.e-37;

   if (rayDirection.z == 0.0)
       rayDirection.z = 1.e-37;

    float terrainBoundsHeight = 10.0;
    int boxWidthInTexels = 64;
    vec3 boxMin = vec3(0, 0, 0);
    vec3 boxMax = vec3(boxWidthInTexels,terrainBoundsHeight,boxWidthInTexels);

    vec2 res = BboxIntersect(rayOrigin, 1.0/rayDirection, boxMin, boxMax, 0.0f, 1000.0f);

    if (res.x > res.y)
        return false;

    ivec3 step = ivec3(sign(rayDirection));        
    vec3 pStart = rayOrigin + res.x*rayDirection;
    ivec3 startTexel = clamp(ivec3(pStart), ivec3(0), ivec3(boxWidthInTexels-1, boxWidthInTexels-1, boxWidthInTexels-1));        

    int X = startTexel.x;
    int Z = startTexel.z;

    // ray marching values
    float tDeltaX = 1.0 / abs(rayDirection.x);
    float tMaxX = (float(startTexel.x) + (step.x > 0 ? 1.0f : 0.0f) - rayOrigin.x) / rayDirection.x;

    float tDeltaZ = 1.0 / abs(rayDirection.z);
    float tMaxZ = (float(startTexel.z) + (step.z > 0 ? 1.0f : 0.0f) - rayOrigin.z) / rayDirection.z;

    bool hit = false;
    float tTexelEntry = res.x;
    float tBBoxExit = res.y;

    // Find out if we start above or below the the heightmap
    vec4 texelHeights = terrainBoundsHeight*SampleHeightMap( ivec2(X,Z));
    vec2 uv = pStart.xz - vec2(X,Z);
    float hMapAtEntry;
    if (uv.x > uv.y)  
    {
        hMapAtEntry = texelHeights[C00] + uv.x * (texelHeights[C10] - texelHeights[C00]) + uv.y * (texelHeights[C11] - texelHeights[C10]);
    }        
    else
    {
        hMapAtEntry = texelHeights[C00] + uv.x * (texelHeights[C11] - texelHeights[C01]) + uv.y * (texelHeights[C01] - texelHeights[C00]);      
    }
    float hitSign = pStart.y - hMapAtEntry > 0.0f ? -1.0f : 1.0f;


    int i = 0;
    while (X >= 0 && Z >= 0 && X < boxWidthInTexels && Z < boxWidthInTexels && tTexelEntry < tBBoxExit && i < 128) 
    {
        float tTexelExit = (tMaxX < tMaxZ) ? tMaxX : tMaxZ;
        float hRayAtExitEdge = rayOrigin.y + tTexelExit*rayDirection.y;    
        float hRayAtEnterEdge = rayOrigin.y + tTexelEntry*rayDirection.y; 

        vec4 texelHeights = terrainBoundsHeight*SampleHeightMap( ivec2(X,Z));

        // ray to texel bbox intersection test for early out
        if (sign(min(hRayAtExitEdge, hRayAtEnterEdge) - max4(texelHeights)) == hitSign || sign(max(hRayAtExitEdge, hRayAtEnterEdge) - min4(texelHeights)) == hitSign)//&& i != 0
        {
            float t1 = IntersectMapTriangle(texelHeights[C00], texelHeights[C10] - texelHeights[C00], texelHeights[C11] - texelHeights[C10], rayOrigin, rayDirection, float(X), float(Z));
            vec2 p1 = rayOrigin.xz - vec2(X,Z) + t1*rayDirection.xz; 
            if (clamp(p1, vec2(0.0), vec2(1.0)) == p1 && p1.x >= p1.y && t1 >= tTexelEntry)
            {
                hitTriangle = 0;
                hit = true;
            }

            float t2 = IntersectMapTriangle(texelHeights[C00], texelHeights[C11] - texelHeights[C01], texelHeights[C01] - texelHeights[C00], rayOrigin, rayDirection, float(X), float(Z));
            vec2 p2 = rayOrigin.xz - vec2(X,Z) + t2*rayDirection.xz; 
            if (clamp(p2, vec2(0.0), vec2(1.0)) == p2  && p2.x <= p2.y && t2 >= tTexelEntry && (!hit || t2 < t1))
            {
                hitTriangle = 1;
                hit = true;
            }

            if (hit)
                break;            
        }

        // Determine coordinates of next texel to visit
        tTexelEntry = tTexelExit;
        if (tMaxX < tMaxZ) 
        {
            tMaxX = tMaxX + tDeltaX;
            X = X + step.x;

        }
        else 
        {
            tMaxZ = tMaxZ + tDeltaZ;
            Z = Z + step.z;
        }
        i++;
    }

    hitTexel = ivec2(X,Z);

    return hit;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

    //Getting camera properties from buffer A
    vec3 cameraPos = getCameraPositionFromBufferA(iChannel0);
    mat3 cameraRotation = getCameraRotationFromBufferA(iChannel0, iResolution.xy);

	//Creating ray
    vec3 rayOrigin = cameraPos;
    vec3 rayDirection = normalize(cameraRotation * uvToCastPlane(uv));
    vec4 col = vec4(0.0);    

    ivec2 hitTexel;
    int hitTriangle;
      //for ( int e = 0; e < 5; e++)  
      float e = 0.0f;
    if (TraceRay(rayOrigin+float(e)*0.000000001f, rayDirection, hitTexel, hitTriangle))
    {
        vec4 texelHeights = 10.0*SampleHeightMap(hitTexel);

        vec3 v1 = vec3(hitTexel.x, texelHeights.w, hitTexel.y);
        vec3 v2 = vec3(hitTexel.x+1, texelHeights.y, hitTexel.y+1);
        vec3 v3 = hitTriangle == 0 ? vec3(hitTexel.x+1, texelHeights.z, hitTexel.y) : vec3(hitTexel.x, texelHeights.x, hitTexel.y+1);
        vec3 normal = hitTriangle == 0 ? normalize(cross(v2-v1, v3-v1)) : -normalize(cross(v2-v1, v3-v1));

        vec3 lightDir = normalize(vec3(0.2,0.2,0.000));
        float lambert = clamp(dot(normal, lightDir), 0.0, 1.0);

        float hitT;
        bool valid = IntersectTriangle(v1, v2, v3, rayOrigin, rayDirection, 0.0f, 10000.0f, hitT);

        vec3 hitPos = rayOrigin + rayDirection*hitT;


        float v = SampleHeightMap(hitTexel).x*lambert;
        //if (hitTriangle == 0)
        //     v*= 0.9;
        col = vec4(v,v,v, 1.0)+0.1;


        if (TraceRay(hitPos+vec3(0, 0.001, 0), lightDir, hitTexel, hitTriangle))
           col *= 0.3;

        col *= vec4(204.0/255.0, 0.0, 102.0/255.0, 1.0);
        if (!valid)
             col = vec4(0.45, 0.0, 0.0, 1.0);

    }
    else
    {
        //Adding grid to the final image
        bool gridVisibility = isGridVisible(iChannel0);
        if (gridVisibility)
        {
            vec4 grid = getGrid(rayOrigin, rayDirection) * 0.3 + 0.1;
            col += grid;
        }
    }



    fragColor = col;
}

