/*
	All code for grid and camera is in Buffer A and Common tabs. Here is just camera and grid usage with very simple raymarching. :)

	How to use:
	iChannel0 - sampler with Buffer A
	getCameraPositionFromBufferA(iChannel0) - returns camera coordinates in 3D space
	getCameraRotationFromBufferA(iChannel0, iResolution.xy) - return rotation matrix for camera.
	isGridVisible(iChannel0) - returns true if grid is enabled, false - otherwise.
	getGrid(rayOrigin, rayDirection) - returns the grid color (vec4).


	I made camera to move just like camera in the Unity editor:
	W A S D Q E keys - Camera movement
	Shift key - Adds more speed to camera movement
	Mouse - Look around
	G - enable/disable grid view
*/
#define BASE_WIDTH 0.006
#define AXIS_WIDTH 0.05

float hash12(vec2 point)
{
    return fract(sin(dot(point, vec2(129.45658, 37.6323))) * 3178.2563);
}

vec3 getCameraPositionFromBufferA(sampler2D bufferA)
{
 	return texture(bufferA, vec2(0.0, 0.0)).xyz;
}

mat3 getCameraRotationFromBufferA(sampler2D bufferA, vec2 resolution)
{

    vec2 cameraAngle = texture(bufferA, vec2(1.2, 0.0) / resolution.xy).xy;

    mat3 cameraRotation = mat3(cos(cameraAngle.x), 0.0, -sin(cameraAngle.x),
                                0.0, 1.0, 0.0,
                                sin(cameraAngle.x), 0.0, cos(cameraAngle.x)) *
        				  mat3(1.0, 0.0, 0.0,
                                  0.0, cos(cameraAngle.y), -sin(cameraAngle.y),
                                  0.0, sin(cameraAngle.y), cos(cameraAngle.y));

    return cameraRotation;
}

bool isGridVisible(sampler2D bufferA)
{
	return (1.0 - texture(bufferA, vec2(0.0, 0.0)).w) > 0.5;
}

//xy - plane uv, z - visibility, w - distance
vec4 castXZPlane(vec3 rayOrigin, vec3 rayDirection)
{
    float mul = 1.0;
    if (rayOrigin.y < 0.0) mul = -1.0;

    vec3 castRayOrigin = rayOrigin;
 	float distToPlane = abs(castRayOrigin.y);
    vec3 castRayDirection = rayDirection / rayDirection.y;
    castRayDirection *= distToPlane;

    castRayOrigin -= mul * castRayDirection;

    return vec4((castRayOrigin).xz, (dot(rayDirection * mul, castRayDirection) < 0.0 ? 1.0 : 0.0), length(castRayDirection));
}

float planeToLines(vec4 plane)
{
 	vec2 uv = fract(plane.xy + 0.5);
    float width = BASE_WIDTH * (plane.w);
    float fade = smoothstep(100.0, -20.0, plane.w);
	return min((smoothstep(width, 0.0, abs(uv.x - 0.5)) + smoothstep(width, 0.0, abs(uv.y - 0.5))) * plane.z, 1.0) * fade;
}

//x - x axis, y - y axis
vec2 planeToAxis(vec4 plane)
{
 	float width = AXIS_WIDTH * (plane.w);
    float fade = smoothstep(100.0, -20.0, plane.w);
    float xAxis = smoothstep(width, 0.0, abs(plane.x)) * smoothstep(0.0, 0.01, plane.y);
    float yAxis = smoothstep(width, 0.0, abs(plane.y)) * smoothstep(0.0, 0.01, plane.x);
    return vec2(xAxis, yAxis) * plane.z * fade;
}

vec4 getGrid(vec3 rayOrigin, vec3 rayDirection)
{
    vec4 xzPlane = castXZPlane(rayOrigin.zyx, rayDirection.zyx);
    float xzLines = planeToLines(xzPlane);
    vec2 xzAxis = planeToAxis(xzPlane);

    vec4 xyPlane = castXZPlane(rayOrigin.yzx, rayDirection.yzx);
    float xyLines = planeToLines(xyPlane);
    vec2 xyAxis = planeToAxis(xyPlane);

    vec4 yzPlane = castXZPlane(rayOrigin.zxy, rayDirection.zxy);
    float yzLines = planeToLines(yzPlane);
    vec2 yzAxis = planeToAxis(yzPlane);

    vec4 grid = vec4(0.0);

    grid += xzLines + vec4(xzAxis.x, 0.0, xzAxis.y, 0.0);
    grid += xyLines + vec4(xyAxis.x, xyAxis.y, 0.0, 0.0);
    grid += yzLines + vec4(0.0, yzAxis.x, yzAxis.y, 0.0);

    return grid;
}

//Shader License: CC BY 3.0
//Author: Jan Mróz (jaszunio15)

/*
	All code for grid and camera is in Buffer A and Common tabs. Here is just camera and grid usage with very simple raymarching. :)

	How to use:
	iChannel0 - sampler with Buffer A
	getCameraPositionFromBufferA(iChannel0) - returns camera coordinates in 3D space
	getCameraRotationFromBufferA(iChannel0, iResolution.xy) - return rotation matrix for camera.
	isGridVisible(iChannel0) - returns true if grid is enabled, false - otherwise.
	getGrid(rayOrigin, rayDirection) - returns the grid color (vec4).


	I made camera to move just like camera in the Unity editor:
	W A S D Q E keys - Camera movement
	Shift key - Adds more speed to camera movement
	Mouse - Look around
	G - enable/disable grid view
*/
#define KEY_W 87
#define KEY_A 65
#define KEY_S 83
#define KEY_D 68
#define KEY_Q 81
#define KEY_E 69
#define KEY_G 71
#define KEY_SHIFT 16

#define GET_KEY(k) (texture(iChannel0, vec2(float(k) / 256.0, 0.1) ).x)
#define GET_TOGGLE(k) (texture(iChannel0, vec2(float(k) / 256.0, 0.9) ).x)
#define PI 3.1419

#define MOVE_SPEED 4.0

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    if (iFrame < 1) //Camera start position and rotation
    {
     	if (fragCoord.x <= 2.0)
        {
            if (fragCoord.x < 1.0)
            {
				fragColor = vec4(30.5, 10.1, 10.5, 0.0);
            }
            else fragColor = vec4(0.0);
        }
    }
    else if (fragCoord.y < 1.0 && fragCoord.x <= 2.0)
    {
        vec2 mousePos = iMouse.xy / iResolution.xy - 0.5;

        if (iMouse.x < 1.0 && iMouse.y < 1.0) mousePos = vec2(0.0); 

        float yaw = mousePos.x * PI * 4.0;
        float pitch = mousePos.y * PI;

        //Same matrix construction as in common tab
        mat3 cameraRotation = mat3(cos(yaw), 0.0, -sin(yaw),
                                0.0, 1.0, 0.0,
                                sin(yaw), 0.0, cos(yaw)) *
            				mat3(1.0, 0.0, 0.0,
                                  0.0, cos(pitch), -sin(pitch),
                                  0.0, sin(pitch), cos(pitch));


        vec3 forward = cameraRotation * vec3(0, 0, 1);
        vec3 right = normalize(cross(vec3(0, 1, 0), forward));
        vec3 up = normalize(cross(forward, right));

        float keyW = GET_KEY(KEY_W);
        float keyA = GET_KEY(KEY_A);
        float keyS = GET_KEY(KEY_S);
        float keyD = GET_KEY(KEY_D);
        float keyQ = GET_KEY(KEY_Q);
        float keyE = GET_KEY(KEY_E);
        float toggleG = GET_TOGGLE(KEY_G);
        float keyShift = GET_KEY(KEY_SHIFT);

        if (fragCoord.x < 1.0)
        {
            float speedBoost = (1.0 + keyShift * 3.0);
            vec3 cameraPos = texture(iChannel1, vec2(0.0, 0.0)).xyz;
            cameraPos += forward * (keyW - keyS) * iTimeDelta * MOVE_SPEED * speedBoost;
            cameraPos += right * (keyD - keyA) * iTimeDelta * MOVE_SPEED * speedBoost;
            cameraPos += up * (keyE - keyQ) * iTimeDelta * MOVE_SPEED * speedBoost;
            fragColor = vec4(cameraPos, toggleG);
        }
        else
        {
            vec2 cameraRotation = vec2(yaw, pitch);
            fragColor = vec4(cameraRotation, 0.0, 0.0);
        }
    }
}
